<template>
  <v-container fluid class="pa-4 pa-md-6">
    <div class="d-flex align-center flex-wrap ga-3 mb-5"><div><div class="text-h4 font-weight-bold">Usuarios</div><div class="text-medium-emphasis">Usuarios vinculados a sus empresas y roles.</div></div><v-spacer /><v-btn color="primary" @click="router.push('/users/form')"><AppIcon name="plus" class="mr-2" />Nuevo usuario</v-btn></div>
    <v-text-field v-model="search" label="Buscar por nombre" class="mb-4" max-width="420"><template #prepend-inner><AppIcon name="search" :size="18" /></template></v-text-field>
    <v-card v-if="!smAndDown" border elevation="0"><v-data-table :items="items" :search="search" density="compact" :items-per-page="10" :headers="headers"><template #item.name="{ item }"><div class="d-flex align-center ga-3"><v-avatar size="36" color="primary"><v-img v-if="item.avatarUrl" :src="item.avatarUrl" /><span v-else>{{ initials(item) }}</span></v-avatar>{{ fullName(item) }}</div></template><template #item.organizationRole="{ item }">{{ roleLabel(item.organizationRole) }}</template><template #item.status="{ item }"><v-chip class="status-chip" size="small" :color="item.status === 'active' ? 'success' : 'warning'">{{ statusLabel(item.status) }}</v-chip></template><template #item.actions="{ item }"><v-btn icon variant="text" size="small" @click="router.push(`/users/form/${item.id}`)"><AppIcon name="edit" :size="18" /></v-btn><v-btn icon variant="text" color="danger" size="small" @click="remove(item)"><AppIcon name="trash" :size="18" /></v-btn></template></v-data-table></v-card>
    <div v-else><v-card v-for="item in mobileItems" :key="item.id" border elevation="0" class="mb-3"><v-card-text class="d-flex align-start ga-3"><v-avatar size="44" color="primary"><v-img v-if="item.avatarUrl" :src="item.avatarUrl" /><span v-else>{{ initials(item) }}</span></v-avatar><div class="flex-grow-1"><div class="font-weight-bold">{{ fullName(item) }}</div><div class="text-caption text-medium-emphasis">{{ item.email }}</div><div class="text-body-2 mt-1">{{ roleLabel(item.organizationRole) }}</div><v-chip class="status-chip mt-2" size="small" :color="item.status === 'active' ? 'success' : 'warning'">{{ statusLabel(item.status) }}</v-chip></div><v-btn icon variant="text" size="small" @click="router.push(`/users/form/${item.id}`)"><AppIcon name="edit" :size="18" /></v-btn></v-card-text></v-card><v-pagination v-model="page" :length="pages" density="compact" size="small" /></div>
  </v-container>
</template>

<script setup lang="ts">
import { computed, onMounted, ref, watch } from "vue"; import { useRouter } from "vue-router"; import { useDisplay } from "vuetify"; import AppIcon from "../components/AppIcon.vue"; import { http } from "../services/http";
interface Member { id: string; firstName: string; lastName: string; secondLastName: string | null; username: string; email: string; avatarUrl: string | null; status: "active" | "disabled"; organizationRole: string | null }
const router = useRouter(); const { smAndDown } = useDisplay(); const items = ref<Member[]>([]); const search = ref(""); const page = ref(1); const perPage = 6; const headers = [{ title: "Usuario", key: "name" }, { title: "Username", key: "username" }, { title: "Correo", key: "email" }, { title: "Rol", key: "organizationRole" }, { title: "Estado", key: "status" }, { title: "", key: "actions", sortable: false }];
const fullName = (item: Member) => `${item.firstName} ${item.lastName} ${item.secondLastName || ""}`.trim(); const initials = (item: Member) => `${item.firstName[0] || ""}${item.lastName[0] || ""}`.toUpperCase(); const roleLabels = ref<Record<string, string>>({}); const roleLabel = (role: string | null) => roleLabels.value[role || ""] || "Sin rol"; const statusLabel = (status: string) => status === "active" ? "Activo" : "Deshabilitado";
const filtered = computed(() => items.value.filter((item) => fullName(item).toLowerCase().includes(search.value.toLowerCase()))); const pages = computed(() => Math.max(1, Math.ceil(filtered.value.length / perPage))); const mobileItems = computed(() => filtered.value.slice((page.value - 1) * perPage, page.value * perPage)); watch(search, () => page.value = 1);
async function load() { const [usersResponse, rolesResponse] = await Promise.all([http.get<{ data: Member[] }>("/platform/users"), http.get<{ company: { code: string; name: string }[] }>("/roles")]); items.value = usersResponse.data.data; roleLabels.value = Object.fromEntries(rolesResponse.data.company.map((role) => [role.code, role.name])); } async function remove(item: Member) { if (!window.confirm(`¿Eliminar definitivamente a ${fullName(item)}?`)) return; try { await http.delete(`/platform/users/${item.id}`); await load(); } catch { window.alert("No puedes eliminar tu propia cuenta."); } } onMounted(load);
</script>
